  2	/// `dmtools upgrade [version]` — Dart port of the Java runtime upgrade
  3	/// (dm.ai #701 parity, gh-395).
  4	///
  5	/// Reachable both as the launcher command `upgrade` and inside the runtime
  6	/// as `mcp upgrade` / `upgrade`, so installs with an OLD launcher (which
  7	/// forwards unknown commands to the runtime) can still upgrade.
  8	///
  9	/// Flow: validate the version (`1.2.3` / `v1.2.3`) before anything is
 10	/// downloaded → download the release `install.sh` (failed download runs
 11	/// nothing) → run it with the version, returning its exit code. The
 12	/// installer replaces both runtime and launcher.
 13	///
 14	/// `DMTOOLS_UPGRADE_DRY_RUN=true` prints the plan and changes nothing.
 15	library;
 16	
 17	import 'dart:typed_data';
 18	import 'dart:io';
 19	
 20	/// Repository hosting the release artifacts and `install.sh`.
 21	const String upgradeRepo = 'epam/dmtools-dart';
 22	
 23	/// Strict semantic version: `1.2.3` or `v1.2.3`.
 24	final RegExp upgradeVersionPattern = RegExp(r'^v?\d+\.\d+\.\d+$');
 25	
 26	/// Downloads the installer script bytes for [url]; throws on failure.
 27	typedef UpgradeDownloader = Future<List<int>> Function(Uri url);
 28	
 29	/// Runs the installer script at [scriptPath] with [args]; returns its exit code.
 30	typedef UpgradeInstallerRunner = Future<int> Function(
 31	  String scriptPath,
 32	  List<String> args,
 33	);
 34	
 35	/// Implements the upgrade command.
 36	class UpgradeCommand {
 37	  /// Creates the command. [dryRun] comes from `DMTOOLS_UPGRADE_DRY_RUN`.
 38	  /// [download] and [runInstaller] are test seams.
 39	  UpgradeCommand({
 40	    required void Function(String line) writer,
 41	    required void Function(String line) errorWriter,
 42	    this.dryRun = false,
 43	    UpgradeDownloader? download,
 44	    UpgradeInstallerRunner? runInstaller,
 45	  })  : _writer = writer,
 46	        _errorWriter = errorWriter,
 47	        _download = download ?? _defaultDownload,
 48	        _runInstaller = runInstaller ?? _defaultRunInstaller;
 49	
 50	  final void Function(String line) _writer;
 51	  final void Function(String line) _errorWriter;
 52	  final UpgradeDownloader _download;
 53	  final UpgradeInstallerRunner _runInstaller;
 54	
 55	  /// When true, nothing is downloaded or executed.
 56	  final bool dryRun;
 57	
 58	  /// Runs the upgrade for [args] (optional version as the first argument).
 59	  /// Returns the exit code.
 60	  Future<int> run(List<String> args) async {
 61	    final version = args.isEmpty ? null : args.first.trim();
 62	    if (version != null && !upgradeVersionPattern.hasMatch(version)) {
 63	      _errorWriter(
 64	        'Error: invalid version "$version" — expected 1.2.3 or v1.2.3',
